<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRemScale } from '../../utils/rem.js'

import { searchCharts } from '../../api/infos.js'
import linkCard from '../../components/cards/linkCard.vue'

useRemScale()

const inputText = ref('')
const chartList = ref([])
const isShowResult = ref(false)
const totalScore = ref(0)

const firstBgImage = computed(() => {
  if (chartList.value.length > 0) {
    return chartList.value[0].imgPath
  }
  return ''
})

const showResult = () => {
  if (chartList.value.length === 0) return
  let sum = 0
  chartList.value.forEach(item => {
    const randomScore = Math.floor(Math.random() * 20001) + 980000
    item.score = randomScore
    sum += randomScore
  })
  totalScore.value = sum
  isShowResult.value = true
}
</script>

<template>
  <div 
    class="bg-overlay"
    v-if="firstBgImage"
    :style="{ backgroundImage: `url(${firstBgImage})` }"
  ></div>

  <div class="input-wrap" v-if="!isShowResult">
    <div class="border-line">
      <input
        v-model="inputText"
        type="text"
        placeholder="点击输入文本"
        class="top-input"
        @input="handleQuery"
        @keyup.enter="handleQuery"
      />
    </div>
  </div>

  <div class="total-score-top" v-if="isShowResult">
    <div>Total Score：{{ totalScore }}</div>
  </div>

  <div class="card-container" v-if="chartList.length > 0">
    <link-card
      v-for="item in chartList"
      :key="item.id"
      :item="item"
      :is-show-result="isShowResult"
    />
  </div>

  <img
    class="playButton"
    src="/assets/part/play.png"
    @click="showResult"
    v-if="!isShowResult"
  />
  
  <div class="copyright-text">phiLinkSimulator | @DaogeMM</div>
</template>

